/**
 * Converts an identifier to snake_case.
 * 
 * @param {string} name
 * @returns {string}
 */
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (name === '') {
    return '';
  }

  // 1. Handle spaces, tabs, and hyphens by converting them to underscores
  let result = name.replace(/[\s\t-]+/g, '_');

  // 2. Insert underscore between lowercase/digit and uppercase
  // e.g., userName -> user_Name, version2Beta -> version2_Beta
  result = result.replace(/([a-z0-9])([A-Z])/g, '$1_$2');

  // 3. Handle runs of capitals:
  // Before the last capital when a lowercase letter follows it
  // e.g., HTTPServer -> HTTP_Server -> http_server
  // We use a lookahead to find a sequence of capitals followed by a lowercase letter
  result = result.replace(/([A-Z])([A-Z])(?=[a-z])/g, '$1_$2');

  // 4. Convert to lowercase
  result = result.toLowerCase();

  // 5. Collapse multiple underscores into one
  // The prompt says: "__init__" becomes "_init_".
  // This implies we should collapse internal runs, but preserve leading/trailing 
  // if they were part of the original structure, or simply collapse all.
  // Re-reading rule 5: "Runs of _ ... collapse into a single _, including at the very start and the very end."
  // Wait, the example "__init__" -> "_init_" suggests we collapse internal runs, 
  // but keep the single underscores at the ends.

  // Let's refine the collapse:
  // Replace multiple underscores with a single underscore
  result = result.replace(/_+/g, '_');

  return result;
}
