/**
 * Roman numerals, strictly
 */

const ROMAN_MAP = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

/**
 * Converts an integer from 1 to 3999 to its Roman numeral.
 * @param {number} n
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let remaining = n;

  for (const [value, symbol] of ROMAN_MAP) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }

  return result;
}

/**
 * Converts a Roman numeral back to a number, strictly.
 * @param {string} text
 * @returns {number}
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string.');
  }

  if (text.length === 0) {
    throw new RangeError('Input cannot be empty.');
  }

  // The regex ensures the string matches the canonical form exactly.
  // M{0,3} matches 0-3000
  // (CM|CD|D?C{0,3}) matches 900, 400, 500-800, 100-300
  // (XC|XL|L?X{0,3}) matches 90, 40, 50-80, 10-30
  // (IX|IV|V?I{0,3}) matches 9, 4, 5-8, 1-3
  const canonicalRegex = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  if (!canonicalRegex.test(text) || text === "") {
    throw new RangeError('Invalid or non-canonical Roman numeral.');
  }

  // Verify that the generated string matches the input to ensure strictness
  // (e.g., prevents empty strings or invalid combinations that regex might miss)
  let n = 0;
  let temp = text;
  for (const [value, symbol] of ROMAN_MAP) {
    while (temp.startsWith(symbol)) {
      n += value;
      temp = temp.slice(symbol.length);
    }
  }

  if (temp !== '' || n === 0 || n > 3999) {
    throw new RangeError('Invalid or non-canonical Roman numeral.');
  }

  // Final check: ensure the input is exactly the canonical form
  if (toRoman(n) !== text) {
    throw new RangeError('Non-canonical Roman numeral provided.');
  }

  return n;
}
