/**
 * Parses a URL query string into an object.
 * 
 * @param {string} query
 * @returns {Object}
 */
export function parseQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError('Query must be a string');
  }

  const result = Object.create(null);
  const seenKeys = new Set();

  if (query.startsWith('?')) {
    query = query.slice(1);
  }

  if (!query) return result;

  const pairs = query.split('&');

  for (const pair of pairs) {
    if (pair === '') continue;

    const firstEq = pair.indexOf('=');
    let rawKey, rawValue;

    if (firstEq === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, firstEq);
      rawValue = pair.slice(firstEq + 1);
    }

    const key = decode(rawKey);
    const value = decode(rawValue);

    const isArrayKey = key.endsWith('[]');
    const finalKey = isArrayKey ? key.slice(0, -2) : key;

    if (!(finalKey in result)) {
      if (isArrayKey) {
        result[finalKey] = [value];
      } else {
        result[finalKey] = value;
      }
    } else {
      if (!Array.isArray(result[finalKey])) {
        result[finalKey] = [result[finalKey]];
      }
      result[finalKey].push(value);
    }
  }

  return result;
}

/**
 * Decodes a query string component.
 * + becomes space, then decodeURIComponent.
 */
function decode(str) {
  const replaced = str.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(replaced);
  } catch (e) {
    throw new RangeError('Malformed percent-escape');
  }
}
