/**
 * Turns text into a URL-safe slug.
 * 
 * @param {string} text 
 * @param {Object} [options]
 * @param {number} [options.maxLength]
 * @returns {string}
 */
export function slugify(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (options.maxLength !== undefined) {
    if (!Number.isInteger(options.maxLength) || options.maxLength <= 0) {
      throw new RangeError('maxLength must be a positive integer');
    }
  }

  // 1. Normalize Unicode NFKD and remove combining marks (U+0300-U+036F)
  let slug = text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');

  // 2. Lowercase
  slug = slug.toLowerCase();

  // 3. Replace non-alphanumeric characters with a single hyphen
  // Note: [^a-z0-9] matches anything that is not a lowercase letter or digit
  slug = slug.replace(/[^a-z0-9]+/g, '-');

  // 4. Remove hyphens from start and end
  slug = slug.replace(/^-+|-+$/g, '');

  // 6. Handle maxLength
  if (options.maxLength !== undefined) {
    slug = slug.substring(0, options.maxLength);
    // Remove hyphens from the end again after cutting
    slug = slug.replace(/-+$/g, '');
  }

  return slug;
}
