/**
 * Converts text to title case according to specific rules.
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') {
    return '';
  }

  const smallWords = new Set(['a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as']);

  // Split by whitespace while keeping the whitespace structure
  const parts = text.split(/(\s+)/);
  const words = parts.filter(p => !/^\s+$/.test(p) && p !== '');

  const processedWords = parts.map((part) => {
    if (/^\s+$/.test(part) || part === '') {
      return part;
    }

    const index = words.indexOf(part);
    const isFirst = index === 0;
    const isLast = index === words.length - 1;

    return processWord(part, isFirst, isLast, smallWords);
  });

  return processedWords.join('');
}

function processWord(word, isFirst, isLast, smallWords) {
  // Rule 2: Hyphenated words
  if (word.includes('-')) {
    return word.split('-').map(part => processWord(part, false, false, smallWords)).join('-');
  }

  // Rule 1: Acronyms
  if (/^[A-Z]{2,}$/.test(word)) {
    return word;
  }

  // Rule 4: Small words
  const lower = word.toLowerCase();
  if (smallWords.has(lower) && !isFirst && !isLast) {
    return lower;
  }

  // Rule 3: Capitalizing
  // Find the first letter (a-z)
  const firstLetterMatch = word.match(/[a-z]/i);
  if (!firstLetterMatch) {
    return word;
  }

  const firstLetterIndex = firstLetterMatch.index;
  const head = word.slice(0, firstLetterIndex);
  const target = word.slice(firstLetterIndex);

  return head + target.charAt(0).toUpperCase() + target.slice(1).toLowerCase();
}
