export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (name === '') {
    return '';
  }

  // 1. Handle camelCase/PascalCase boundaries:
  // - Between lowercase/digit and uppercase: "aB" -> "a_B"
  // - Between a run of capitals and a lowercase letter: "ABc" -> "A_Bc"
  // We use a regex to insert underscores at these boundaries.

  let result = name
    // Insert underscore between lowercase/digit and uppercase
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    // Insert underscore before the last capital in a sequence followed by lowercase
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  // 2. Replace spaces, tabs, and hyphens with underscores
  result = result.replace(/[\s-]+/g, '_');

  // 3. Convert to lowercase
  result = result.toLowerCase();

  // 4. Collapse multiple underscores into one
  // Note: The requirement says "__init__" becomes "_init_".
  // This implies we should only collapse internal runs, 
  // but the rule says "including at the very start and the very end".
  // Let's re-read: "__init__" -> "_init_". 
  // This means we collapse runs of 2+ into 1, but keep single leading/trailing.
  result = result.replace(/_+/g, (match) => {
    return match.length > 1 ? '_' : match;
  });

  return result;
}
