/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex breakdown:
  // ^\s* matches start
  // (\d+(?:\.\d+)?) matches a number (must have digits before and after decimal if present)
  // ([a-z]+) matches the unit
  // \s* matches optional whitespace between components
  // Global flag to find all components
  const componentRegex = /(\d+(?:\.\d+)?)([a-z]+)/g;

  let totalMs = 0;
  let matches = 0;
  const seenUnits = new Set();

  // Validate that the entire string is composed only of valid components and whitespace
  // We replace all valid components with empty string; if anything remains, it's invalid.
  let remaining = trimmed.replace(componentRegex, (match, val, unit) => {
    if (!units.hasOwnProperty(unit)) {
      throw new RangeError(`Invalid unit: ${unit}`);
    }
    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    seenUnits.add(unit);
    totalMs += parseFloat(val) * units[unit];
    matches++;
    return '';
  });

  if (remaining.trim() !== '' || matches === 0) {
    throw new RangeError('Invalid format');
  }

  return Math.round(totalMs);
}
