/**
 * Parses a single line of CSV.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} if input is not a string
 * @throws {RangeError} if line is malformed
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;
  const n = line.length;

  while (i <= n) {
    if (i < n && line[i] === '"') {
      // Quoted field
      let field = '';
      i++; // skip opening quote
      let closed = false;

      while (i < n) {
        if (line[i] === '"') {
          if (i + 1 < n && line[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            closed = true;
            i++; // skip closing quote
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Quoted field not closed');
      }

      // After closing quote, must be comma or end of string
      if (i < n && line[i] !== ',') {
        throw new RangeError('Invalid character after closing quote');
      }

      result.push(field);
      i++; // skip comma
    } else {
      // Unquoted field
      let start = i;
      let field = '';
      while (i < n && line[i] !== ',') {
        if (line[i] === '"') {
          throw new RangeError('Quote inside unquoted field');
        }
        field += line[i];
        i++;
      }
      result.push(field);
      i++; // skip comma
    }
  }

  // Handle trailing comma case: "a," should be ["a", ""]
  if (line.endsWith(',')) {
    result.push('');
  }

  return result;
}
