/**
 * Converts text to title case according to specific rules.
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') {
    return '';
  }

  const smallWords = new Set(['a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as']);

  // Split by whitespace but keep the whitespace structure
  const parts = text.split(/(\s+)/);
  const words = [];
  const wordIndices = [];

  for (let i = 0; i < parts.length; i++) {
    if (!/^\s+$/.test(parts[i])) {
      words.push(parts[i]);
      wordIndices.push(i);
    }
  }

  const processWord = (word, isFirstOrLast) => {
    // Rule 1: Acronyms
    if (/^[A-Z]{2,}$/.test(word)) {
      return word;
    }

    // Rule 2: Hyphenated words
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false)).join('-');
    }

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirstOrLast) {
      return lower;
    }

    // Rule 3: Capitalizing
    const chars = word.toLowerCase().split('');
    for (let i = 0; i < chars.length; i++) {
      if (/[a-z]/.test(chars[i])) {
        chars[i] = chars[i].toUpperCase();
        break;
      }
    }
    return chars.join('');
  };

  for (let i = 0; i < wordIndices.length; i++) {
    const idx = wordIndices[i];
    const isFirstOrLast = (i === 0 || i === wordIndices.length - 1);
    parts[idx] = processWord(parts[idx], isFirstOrLast);
  }

  return parts.join('');
}
