 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} if input is not a string
 * @throws {RangeError} if the CSV format is invalid
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;
  const len = line.length;

  // Handle empty input as a single empty field
  if (len === 0) {
    return [""];
  }

  while (i <= len) {
    if (i < len && line[i] === '"') {
      // Quoted field
      let field = "";
      i++; // Skip opening quote
      let closed = false;

      while (i < len) {
        if (line[i] === '"') {
          if (i + 1 < len && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Unclosed quoted field');
      }

      // After closing quote, must be comma or end of line
      if (i < len && line[i] !== ',') {
        throw new RangeError('Invalid character after closing quote');
      }

      result.push(field);
      i++; // Skip comma
    } else {
      // Unquoted field
      let field = "";
      while (i < len && line[i] !== ',') {
        if (line[i] === '"') {
          throw new RangeError('Quote inside unquoted field');
        }
        field += line[i];
        i++;
      }
      result.push(field);
      i++; // Skip comma
    }

    // If the line ends with a comma, we need one more empty field
    if (i === len + 1 && line[len - 1] === ',') {
      result.push("");
    }
  }

  return result;
}
