/**
 * A Least-Recently-Used (LRU) cache implementation.
 * Uses a Map to store entries. Since ES6 Map preserves insertion order,
 * we can maintain the LRU order by deleting and re-inserting keys
 * whenever they are accessed or updated.
 */
export class LruCache {
  #capacity;
  #cache;

  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1.");
    }
    this.#capacity = capacity;
    this.#cache = new Map();
  }

  get(key) {
    if (!this.#cache.has(key)) {
      return undefined;
    }
    // Refresh the key: remove and re-insert to move to the end (most recent)
    const value = this.#cache.get(key);
    this.#cache.delete(key);
    this.#cache.set(key, value);
    return value;
  }

  set(key, value) {
    if (this.#cache.has(key)) {
      // Update existing: remove to re-insert at the end
      this.#cache.delete(key);
    } else if (this.#cache.size >= this.#capacity) {
      // Evict the least recently used (the first key in the Map)
      const firstKey = this.#cache.keys().next().value;
      this.#cache.delete(firstKey);
    }
    this.#cache.set(key, value);
    return this;
  }

  has(key) {
    return this.#cache.has(key);
  }

  delete(key) {
    return this.#cache.delete(key);
  }

  get size() {
    return this.#cache.size;
  }

  keys() {
    return Array.from(this.#cache.keys());
  }
}
