/**
 * Wraps text into lines of at most width characters.
 * 
 * @param {string} text 
 * @param {number} width 
 * @returns {string[]}
 */
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('width must be an integer at least 1');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) {
    return [];
  }

  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    // If word is longer than width, break it into pieces
    if (word.length > width) {
      // Finish current line if it exists
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }

      // Break word into chunks of width
      for (let i = 0; i < word.length; i += width) {
        const chunk = word.slice(i, i + width);
        if (chunk.length === width) {
          lines.push(chunk);
        } else {
          // Last piece becomes the start of a new currentLine
          currentLine = [chunk];
          currentLength = chunk.length;
        }
      }
    } else {
      // Check if word fits in current line
      // Need: currentLength + (space if not empty) + word.length <= width
      const spaceNeeded = currentLine.length > 0 ? 1 : 0;
      if (currentLength + spaceNeeded + word.length <= width) {
        currentLine.push(word);
        currentLength += spaceNeeded + word.length;
      } else {
        // Start new line
        lines.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}
