/**
 * Converts an identifier to snake_case.
 * 
 * @param {string} name
 * @returns {string}
 */
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (name === '') {
    return '';
  }

  // 1. Handle spaces, tabs, and hyphens by converting them to underscores
  let result = name.replace(/[\s\t-]+/g, '_');

  // 2. Insert underscore between lowercase/digit and uppercase
  // e.g., userName -> user_Name, version2Beta -> version2_Beta
  result = result.replace(/([a-z0-9])([A-Z])/g, '$1_$2');

  // 3. Insert underscore before the last capital in a run of capitals 
  // followed by a lowercase letter
  // e.g., HTTPServer -> HTTP_Server
  result = result.replace(/([A-Z])([A-Z])([a-z])/g, '$1_$2$3');

  // 4. Convert to lowercase
  result = result.toLowerCase();

  // 5. Collapse multiple underscores into one
  // Note: The requirement says "__init__" becomes "_init_".
  // This implies we only collapse internal runs, or keep leading/trailing if they exist.
  // Actually, standard snake_case usually trims, but the prompt says:
  // "Runs of _ collapse into a single _, including at the very start and the very end."
  // This means "__init__" -> "_init_".
  result = result.replace(/_+/g, '_');

  return result;
}
