    .replace(/^-+|-+$/g, '');

  // 6. Handle maxLength
  if (options.maxLength !== undefined) {
    slug = slug.substring(0, options.maxLength);
    // Remove trailing hyphens again after truncation
    slug = slug.replace(/-+$/g, '');
