/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 1000
  };

  // Regex breakdown:
  // ^\s* matches start
  // (\d+(?:\.\d+)?) matches number (no leading/trailing dots)
  // (ms|s|m|h|d|w) matches unit
  // (?:\s+|$) matches separator or end
  const componentRegex = /^(\d+(?:\.\d+)?)(ms|s|m|h|d|w)$/;
  const parts = trimmed.split(/\s+/);
  const seenUnits = new Set();
  let totalMs = 0;

  for (const part of parts) {
    const match = part.match(componentRegex);
    if (!match) {
      throw new RangeError('Invalid format');
    }

    const [, valueStr, unit] = match;

    if (seenUnits.has(unit)) {
      throw new RangeError('Duplicate unit');
    }
    seenUnits.add(unit);

    const value = parseFloat(valueStr);
    totalMs += value * units[unit];
  }

  return Math.round(totalMs);
}
