 * 
 * @param {Array} items - The array of items to group.
 * @param {string|Function} key - The property name or a function to determine the group key.
 * @returns {Map} A Map where keys are the group identifiers and values are arrays of items.
 * @throws {TypeError} If items is not an array or key is not a string or function.
 */
export function groupBy(items, key) {
  if (!Array.isArray(items)) {
    throw new TypeError("The first argument must be an array.");
  }

  const isKeyString = typeof key === 'string';
  const isKeyFunction = typeof key === 'function';

  if (!isKeyString && !isKeyFunction) {
    throw new TypeError("The second argument must be a string or a function.");
  }

  const map = new Map();

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    let groupKey;

    if (isKeyString) {
      // If item is null or undefined, access results in undefined
      if (item === null || item === undefined) {
        groupKey = undefined;
      } else {
        groupKey = item[key];
      }
    } else {
      groupKey = key(item, i);
    }

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  }

  return map;
