 * Converts text to title case according to specific rules.
 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') return '';

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split by whitespace but keep the whitespace structure
  // Using a regex with capturing group to keep delimiters
  const parts = text.split(/(\s+)/);

  const words = parts.map((part, index) => {
    // If it's whitespace, return as is
    if (/^\s+$/.test(part)) return part;

    // Split by hyphens for Rule 2
    const subParts = part.split('-');
    const processedSubParts = subParts.map((sub, subIndex) => {
      return processWord(sub, false);
    });

    const hyphenated = processedSubParts.join('-');

    // Rule 4: Small words
    // We need to know if this is the first or last word in the whole string
    // Filter out whitespace parts to find the actual word index
    const allWords = parts.filter(p => !/^\s+$/.test(p));
    const wordIndex = allWords.indexOf(part);
    const isFirst = wordIndex === 0;
    const isLast = wordIndex === allWords.length - 1;

    const lower = hyphenated.toLowerCase();
    if (smallWords.has(lower) && !isFirst && !isLast) {
      return lower;
    }

    return hyphenated;
  });

  return words.join('');
}

function processWord(word, isHyphenatedPart) {
  // Rule 1: Acronyms
  if (/^[A-Z]{2,}$/.test(word)) {
    return word;
  }

  // Rule 3: Capitalizing
  const lower = word.toLowerCase();
  let result = lower.split('');

  // Find first letter (a-z)
  for (let i = 0; i < result.length; i++) {
    if (/[a-z]/.test(result[i])) {
      result[i] = result[i].toUpperCase();
      break;
    }
  }

  return result.join('');
}
