/**
 * LruCache implementation using a Map.
 * In JavaScript, Map preserves insertion order. By deleting and re-inserting
 * a key, we can move it to the "most recently used" position (the end of the map).
 */
export class LruCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1");
    }
    this._capacity = capacity;
    this._map = new Map();
  }

  get(key) {
    if (!this._map.has(key)) {
      return undefined;
    }
    const value = this._map.get(key);
    // Refresh position: delete and re-insert
    this._map.delete(key);
    this._map.set(key, value);
    return value;
  }

  set(key, value) {
    if (this._map.has(key)) {
      this._map.delete(key);
    } else if (this._map.size >= this._capacity) {
      // Evict the least recently used (the first item in the Map)
      const firstKey = this._map.keys().next().value;
      this._map.delete(firstKey);
    }
    this._map.set(key, value);
    return this;
  }

  has(key) {
    return this._map.has(key);
  }

  delete(key) {
    return this._map.delete(key);
  }

  get size() {
    return this._map.size;
  }

  keys() {
    return Array.from(this._map.keys());
  }
}
