/**
 * Splits items into consecutive groups of size.
 * @param {Array} items 
 * @param {number} size 
 * @returns {Array[]}
 */
export function chunk(items, size) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }
  if (typeof size !== 'number' || !Number.isInteger(size) || size < 1) {
    throw new RangeError('size must be an integer of at least 1');
  }

  const result = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

/**
 * Flattens nested arrays up to a specific depth.
 * @param {Array} items 
 * @param {number} depth 
 * @returns {Array}
 */
export function flatten(items, depth = 1) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }

  const isDepthValid =
    depth === Infinity ||
    (typeof depth === 'number' && Number.isInteger(depth) && depth >= 0);

  if (!isDepthValid) {
    throw new RangeError('depth must be a non-negative integer or Infinity');
  }

  function recursiveFlatten(arr, currentDepth) {
    let result = [];
    for (const item of arr) {
      if (currentDepth > 0 && Array.isArray(item)) {
        result.push(...recursiveFlatten(item, currentDepth - 1));
      } else {
        result.push(item);
      }
    }
    return result;
  }

  return recursiveFlatten(items, depth);
}
