/**
 * A token-bucket rate limiter with an explicit clock.
 */
export class TokenBucket {
  #capacity;
  #refillPerSecond;
  #tokens;
  #lastTimeMs;

  /**
   * @param {number} capacity
   * @param {number} refillPerSecond
   * @param {number} [startTimeMs=0]
   */
  constructor(capacity, refillPerSecond, startTimeMs = 0) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive integer");
    }
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond <= 0) {
      throw new RangeError("refillPerSecond must be a positive, finite number");
    }
    if (typeof startTimeMs !== 'number' || !Number.isFinite(startTimeMs)) {
      throw new RangeError("startTimeMs must be a finite number");
    }

    this.#capacity = capacity;
    this.#refillPerSecond = refillPerSecond;
    this.#tokens = capacity;
    this.#lastTimeMs = startTimeMs;
  }

  /**
   * Updates the bucket state to the given time and returns current token count.
   * @param {number} nowMs
   * @returns {number}
   */
  available(nowMs) {
    if (typeof nowMs !== 'number' || !Number.isFinite(nowMs)) {
      throw new RangeError("nowMs must be a finite number");
    }

    if (nowMs > this.#lastTimeMs) {
      const elapsedSeconds = (nowMs - this.#lastTimeMs) / 1000;
      const addedTokens = elapsedSeconds * this.#refillPerSecond;
      this.#tokens = Math.min(this.#capacity, this.#tokens + addedTokens);
      this.#lastTimeMs = nowMs;
    }

    return this.#tokens;
  }

  /**
   * Attempts to take tokens from the bucket.
   * @param {number} count
   * @param {number} nowMs
   * @returns {boolean}
   */
  tryTake(count, nowMs) {
    if (!Number.isInteger(count) || count <= 0) {
      throw new RangeError("count must be a positive integer");
    }

    const currentTokens = this.available(nowMs);

    if (count > this.#capacity) {
      return false;
    }

    if (currentTokens >= count) {
      this.#tokens -= count;
      return true;
    }

    return false;
  }
}
