    for (let i = 1; i < sorted.length; i++) {
      const next = sorted[i];

      // If the next interval starts before or exactly when the current ends, merge
      if (next[0] <= current[1]) {
        current[1] = Math.max(current[1], next[1]);
      } else {
        // Push the completed interval and move to the next
        result.push(current);
        current = [...next];
      }
    }
    result.push(current);
  }

  return result;
}
