/**
 * Roman numerals, strictly
 */

const ROMAN_MAP = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

/**
 * Converts an integer from 1 to 3999 to its Roman numeral.
 * @param {number} n 
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999');
  }

  let result = '';
  let remaining = n;

  for (const [value, symbol] of ROMAN_MAP) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }

  return result;
}

/**
 * Converts a Roman numeral back to a number, strictly.
 * @param {string} text 
 * @returns {number}
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }
  if (text.length === 0) {
    throw new RangeError('Input cannot be empty');
  }

  // The strict requirement: fromRoman(toRoman(n)) must be n.
  // We can validate this by generating the canonical form for the 
  // potential number and comparing it to the input.

  let n = 0;
  let tempText = text;

  for (const [value, symbol] of ROMAN_MAP) {
    while (tempText.startsWith(symbol)) {
      n += value;
      tempText = tempText.slice(symbol.length);
    }
  }

  // If there's leftover text, it wasn't a valid Roman numeral
  if (tempText.length > 0) {
    throw new RangeError('Invalid Roman numeral');
  }

  // Verify canonical form
  if (toRoman(n) !== text) {
    throw new RangeError('Non-canonical Roman numeral');
  }

  return n;
}
