/**
 * Converts an identifier to snake_case.
 * 
 * @param {string} name
 * @returns {string}
 * @throws {TypeError}
 */
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (name === '') {
    return '';
  }

  // 1 & 2: Insert underscores before capital letters
  // Rule 1: Between lowercase/digit and capital: (a|d)(A)
  // Rule 2: Inside run of capitals before last capital if followed by lowercase: (A)(A)(a) -> (A)_(A)(a)
  let result = name
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  // 3: Replace spaces, tabs, and hyphens with underscores
  result = result.replace(/[\s-]+/g, '_');

  // 4: Convert to lowercase
  result = result.toLowerCase();

  // 5: Collapse runs of underscores
  // Note: The rule says "__init__" becomes "_init_". 
  // This implies we don't trim leading/trailing underscores, just collapse them.
  result = result.replace(/_+/g, '_');

  return result;
}
