/**
 * Parses a single line of CSV.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} if input is not a string
 * @throws {RangeError} if line is malformed
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;
  const len = line.length;

  while (i <= len) {
    if (i < len && line[i] === '"') {
      // Quoted field
      let field = "";
      i++; // skip opening quote
      let closed = false;

      while (i < len) {
        if (line[i] === '"') {
          if (i + 1 < len && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Quoted field not closed');
      }

      // After closing quote, must be comma or end of string
      if (i < len && line[i] !== ',') {
        throw new RangeError('Malformed CSV: content after closing quote');
      }

      result.push(field);
      i++; // skip comma
    } else {
      // Unquoted field
      let field = "";
      let start = i;
      while (i < len && line[i] !== ',') {
        if (line[i] === '"') {
          throw new RangeError('Double quote inside unquoted field');
        }
        field += line[i];
        i++;
      }
      result.push(field);
      i++; // skip comma
    }

    // Handle trailing comma case
    if (i === len + 1 && line[len - 1] === ',') {
      result.push("");
    }
  }

  return result;
}
