/**
 * Compares two semantic version strings.
 * 
 * @param {string} a
 * @param {string} b
 * @returns {number} -1, 0, or 1
 */
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new TypeError('Arguments must be strings');
  }

  const parse = (v) => {
    const regex = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = v.match(regex);
    if (!match) throw new RangeError('Invalid semantic version');

    const major = parseInt(match[1], 10);
    const minor = parseInt(match[2], 10);
    const patch = parseInt(match[3], 10);
    const prerelease = match[4] ? match[4].split('.') : null;

    return { major, minor, patch, prerelease };
  };

  const v1 = parse(a);
  const v2 = parse(b);

  // 1. Compare MAJOR, MINOR, PATCH
  if (v1.major !== v2.major) return v1.major > v2.major ? 1 : -1;
  if (v1.minor !== v2.minor) return v1.minor > v2.minor ? 1 : -1;
  if (v1.patch !== v2.patch) return v1.patch > v2.patch ? 1 : -1;

  // 2. Compare PRERELEASE
  // A version with a prerelease is lower than the same version without one
  if (v1.prerelease && !v2.prerelease) return -1;
  if (!v1.prerelease && v2.prerelease) return 1;
  if (!v1.prerelease && !v2.prerelease) return 0;

  // 3. Compare prerelease identifiers
  const len = Math.min(v1.prerelease.length, v2.prerelease.length);
  for (let i = 0; i < len; i++) {
    const p1 = v1.prerelease[i];
    const p2 = v2.prerelease[i];

    const isN1 = /^\d+$/.test(p1);
    const isN2 = /^\d+$/.test(p2);

    if (isN1 && isN2) {
      const n1 = parseInt(p1, 10);
      const n2 = parseInt(p2, 10);
      if (n1 !== n2) return n1 > n2 ? 1 : -1;
    } else if (!isN1 && !isN2) {
      if (p1 !== p2) return p1 > p2 ? 1 : -1;
    } else {
      // Numeric is lower than alphanumeric
      return isN1 ? -1 : 1;
    }
  }

  // If all shared identifiers are equal, the one with fewer identifiers is lower
  if (v1.prerelease.length !== v2.prerelease.length) {
    return v1.prerelease.length > v2.prerelease.length ? 1 : -1;
  }

  return 0;
}
