/**
 * Parses a URL query string into an object.
 * 
 * @param {string} query
 * @returns {Object}
 */
export function parseQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError('Query must be a string');
  }

  const result = Object.create(null);
  const rawQuery = query.startsWith('?') ? query.slice(1) : query;

  if (!rawQuery) return result;

  const pairs = rawQuery.split('&');

  const decode = (str) => {
    const replaced = str.replace(/\+/g, ' ');
    try {
      return decodeURIComponent(replaced);
    } catch (e) {
      throw new RangeError('Malformed percent-encoding');
    }
  };

  const entries = [];

  for (const pair of pairs) {
    if (pair === '') continue;

    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = decode(pair);
      value = '';
    } else {
      key = decode(pair.substring(0, eqIndex));
      value = decode(pair.substring(eqIndex + 1));
    }

    let isArray = false;
    if (key.endsWith('[]')) {
      key = key.slice(0, -2);
      isArray = true;
    }

    entries.push({ key, value, isArray });
  }

  for (const { key, value, isArray } of entries) {
    if (!(key in result)) {
      if (isArray) {
        result[key] = [value];
      } else {
        result[key] = value;
      }
    } else {
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(value);
    }
  }

  return result;
}
